function munitoAPIError(status,data,apiKey){
 let detail=typeof data?.error?.message==='string'?data.error.message:typeof data?.message==='string'?data.message:'';
 if(apiKey)detail=detail.split(apiKey).join('[key]');
 let message;
 if(status===400)message=aiText('MunitoAI отклонил запрос. Проверьте модель и объём задания.','MunitoAI сұранысты қабылдамады. Модельді және тапсырма көлемін тексеріңіз.');
 else if(status===401)message=aiText('MunitoAI отклонил API-ключ. Проверьте его в консоли MunitoAI.','MunitoAI API кілтін қабылдамады. Оны MunitoAI консолінде тексеріңіз.');
 else if(status===402)message=aiText('MunitoAI приостановил платный доступ. Проверьте оплату в консоли.','MunitoAI ақылы қолжетімділікті тоқтатты. Консольдегі төлемдерді тексеріңіз.');
 else if(status===403)message=aiText('Нет доступа к MunitoAI. Проверьте разрешение Inference, состояние аккаунта и верификацию.','MunitoAI рұқсаты жоқ. Inference рұқсатын, аккаунт күйін және верификацияны тексеріңіз.');
 else if(status===404)message=aiText('Модель MunitoAI недоступна. Обновите список моделей и выберите доступную.','MunitoAI моделі қолжетімсіз. Модельдер тізімін жаңартып, қолжетімді модельді таңдаңыз.');
 else if(status===413)message=aiText('Запрос слишком большой. Сократите задание или объём контекста.','Сұраныс тым үлкен. Тапсырманы немесе контекст көлемін азайтыңыз.');
 else if(status===429)message=aiText('Достигнут лимит MunitoAI. Проверьте квоту и баланс; при временном ограничении повторите запрос позже.','MunitoAI лимитіне жетті. Квота мен балансты тексеріңіз; уақытша шектеу болса, кейінірек қайталаңыз.');
 else if(status===504)message=aiText('MunitoAI не ответил вовремя. Повторите запрос позже.','MunitoAI уақытында жауап бермеді. Кейінірек қайталаңыз.');
 else if(status>=500)message=aiText('MunitoAI временно недоступен. Повторите запрос позже.','MunitoAI уақытша қолжетімсіз. Кейінірек қайталаңыз.');
 else message=aiText('Ошибка MunitoAI API.','MunitoAI API қатесі.');
 const error=new Error(message+' (HTTP '+status+')'+(detail?' '+detail:''));error.status=status;return error;
}
async function munitoRequest(path,{apiKey='',body,timeoutMs=100000}={}){
 if(location.protocol==='file:')throw backendLaunchError();
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);
 let response,data;
 try{
  response=await fetch('/api'+path,{method:body?'POST':'GET',headers:{'X-Ustazera-Client':'1',...(apiKey?{'Authorization':'Bearer '+apiKey}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:controller.signal,cache:'no-store'});
  data=await response.json().catch(()=>null);
  if(controller.signal.aborted)throw new DOMException('Timeout','AbortError');
 }catch(error){
  if(controller.signal.aborted||error.name==='AbortError')throw new Error(aiText('Запрос MunitoAI превысил время ожидания. Повторите его позже.','MunitoAI сұранысының күту уақыты аяқталды. Кейінірек қайталаңыз.'));
  throw backendLaunchError();
 }finally{clearTimeout(timer)}
 if(!response.ok)throw munitoAPIError(response.status,data,apiKey);
 if(!data||typeof data!=='object'||Array.isArray(data))throw new Error(aiText('MunitoAI вернул некорректный JSON-ответ.','MunitoAI қате JSON жауабын қайтарды.'));
 return data;
}
