async function generateMunito(prompt,apiKey,model,{maxTokens=AI_TOKEN_LIMITS.material,onModel}={}){
 apiKey=normalizeAIKey(apiKey);model=normalizeAIModel(model);await validateAISettings(apiKey,model);
 const data=await munitoRequest('/chat/completions',{apiKey,body:{model,messages:[{role:'system',content:SYS+ECONOMY_INSTRUCTION},{role:'user',content:String(prompt)}],max_tokens:maxTokens,reasoning_effort:'none',stream:false}});
 const choice=data.choices?.[0],finish=choice?.finish_reason;
 if(finish==='length')throw new Error(aiText('Ответ MunitoAI оборвался из-за лимита длины. Сократите задание и повторите генерацию.','MunitoAI жауабы ұзындық лимитіне жетіп үзілді. Тапсырманы қысқартып, генерацияны қайталаңыз.'));
 if(finish==='content_filter'||choice?.message?.refusal)throw new Error(aiText('MunitoAI отклонил содержание запроса. Переформулируйте его.','MunitoAI сұраныс мазмұнын қабылдамады. Оны қайта тұжырымдаңыз.'));
 if(finish&&finish!=='stop')throw new Error(aiText('MunitoAI не завершил текстовый ответ. Причина: ','MunitoAI мәтіндік жауапты аяқтамады. Себебі: ')+finish);
 const content=choice?.message?.content;
 const text=(typeof content==='string'?content:Array.isArray(content)?content.filter(part=>part.type==='text'&&typeof part.text==='string').map(part=>part.text).join(''):'').trim();
 if(!text)throw new Error(aiText('MunitoAI вернул пустой текстовый ответ. Повторите генерацию или выберите другую модель.','MunitoAI бос мәтіндік жауап қайтарды. Генерацияны қайталаңыз немесе басқа модель таңдаңыз.'));
 if(onModel)onModel(typeof data.model==='string'?data.model:model);
 return text;
}
async function askAI(prompt,options={}){return generateMunito(prompt,'',getAIModel(),options)}
async function listMunitoModels(apiKey){
 apiKey=normalizeAIKey(apiKey);await validateAISettings(apiKey,DEFAULT_AI_MODEL);
 const data=await munitoRequest('/models',{apiKey,timeoutMs:20000});
 if(!Array.isArray(data.data))throw new Error(aiText('MunitoAI не вернул список моделей.','MunitoAI модельдер тізімін қайтармады.'));
 // The model list also contains dedicated OCR and decision endpoints.
 const ids=[...new Set(data.data.map(model=>model.id).filter(id=>typeof id==='string'&&/^[a-zA-Z0-9][a-zA-Z0-9._\/-]{0,199}$/.test(id)&&!/ocr|decider/i.test(id)))].sort((a,b)=>a===DEFAULT_AI_MODEL?-1:b===DEFAULT_AI_MODEL?1:a.localeCompare(b));
 if(!ids.length)throw new Error(aiText('Не найдены чат-модели MunitoAI. Проверьте доступ аккаунта.','MunitoAI чат-модельдері табылмады. Аккаунт рұқсатын тексеріңіз.'));
 return ids;
}
async function loadAIModelsInto(keyInput,modelInput,status,button){
 const key=normalizeAIKey(keyInput.value),selectedModel=modelInput.value;button.disabled=true;status.textContent=aiText('Загрузка моделей MunitoAI…','MunitoAI модельдері жүктелуде…');
 try{
  const ids=await listMunitoModels(key);
  if(normalizeAIKey(keyInput.value)!==key){status.textContent=aiText('Ключ изменился. Загрузите модели заново.','Кілт өзгерді. Модельдерді қайта жүктеңіз.');return}
  $('modelList').innerHTML=ids.map(id=>'<option value="'+esc(id)+'"></option>').join('');
  if(modelInput.value===selectedModel&&!ids.includes(normalizeAIModel(modelInput.value)))modelInput.value=ids[0];
  status.textContent=aiText('Чат-моделей MunitoAI: ','MunitoAI чат-модельдер саны: ')+ids.length+'. '+aiText('Выбрана: ','Таңдалғаны: ')+modelInput.value;
 }catch(error){status.textContent=error.message}finally{button.disabled=false}
}
async function checkAIConnection(keyInput,modelInput,status,button){
 const key=normalizeAIKey(keyInput.value),model=normalizeAIModel(modelInput.value);let actualModel=model;
 const unchanged=()=>normalizeAIKey(keyInput.value)===key&&normalizeAIModel(modelInput.value)===model;
 button.disabled=true;status.textContent=aiText('Проверка генерации MunitoAI…','MunitoAI генерациясы тексерілуде…');
 try{await generateMunito('Reply with exactly OK.',key,model,{maxTokens:AI_TOKEN_LIMITS.check,onModel:name=>actualModel=name});status.textContent=unchanged()?aiText('MunitoAI API работает. Модель: ','MunitoAI API жұмыс істейді. Модель: ')+actualModel:aiText('Настройки изменились. Повторите проверку.','Баптаулар өзгерді. Тексеруді қайталаңыз.')}catch(error){status.textContent=unchanged()?error.message:aiText('Настройки изменились. Повторите проверку.','Баптаулар өзгерді. Тексеруді қайталаңыз.')}finally{button.disabled=false}
}
