// Keep all local records; send only aggregate results and a short relevant sample.
function buildChatContext(question){
 const grades=DB.grades||[],students=DB.students||[],byStudent=new Map(),byTopic=new Map();let total=0,count=0;
 for(const grade of grades){
  const score=Number(grade.score);if(grade.score==null||grade.score===''||!Number.isFinite(score))continue;
  total+=score;count++;
  for(const [map,key] of [[byStudent,grade.code],[byTopic,grade.topic]]){if(!key)continue;const item=map.get(key)||{sum:0,count:0};item.sum+=score;item.count++;map.set(key,item)}
 }
 const average=item=>Math.round(item.sum/item.count);
 const summary={students:students.length,grades:grades.length,average:count?Math.round(total/count):null,needsSupport:[...byStudent].map(([code,item])=>({code,average:average(item)})).filter(item=>item.average<75).sort((a,b)=>a.average-b.average).slice(0,8),difficultTopics:[...byTopic].map(([topic,item])=>({topic,average:average(item),count:item.count})).sort((a,b)=>a.average-b.average).slice(0,6),savedPackages:(DB.packages||[]).length};
 const codes=[...new Set([...students.map(student=>student.code),...grades.map(grade=>grade.code)].filter(Boolean))];
 const relevant=codes.filter(code=>{const escaped=String(code).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return new RegExp('(^|[^\\p{L}\\p{N}_])'+escaped+'(?=$|[^\\p{L}\\p{N}_])','iu').test(question)}).slice(0,5);
 const details=students.filter(student=>relevant.includes(student.code)).map(student=>({code:student.code,group:student.group,level:student.level,notes:String(student.notes||'').slice(0,180)}));
 const recent=grades.filter(grade=>!relevant.length||relevant.includes(grade.code)).slice().sort((a,b)=>(b.date||0)-(a.date||0)).slice(0,relevant.length?10:6).map(grade=>({code:grade.code,topic:grade.topic,score:grade.score,test:grade.test,practice:grade.practice,note:String(grade.note||'').slice(0,120)}));
 // botSend already appended the current question; do not duplicate it in history.
 const history=(DB.chat||[]).slice(0,-1).slice(-4).map(message=>({role:message.role,text:String(message.text||'').slice(0,800)}));
 return 'Платформа деректерінің қысқа қорытындысы (барлық бағалар бойынша есептелген): '+JSON.stringify(summary)+'.\nАталған студенттер: '+JSON.stringify(details)+'.\nСоңғы бағалар үлгісі (толық тарих емес): '+JSON.stringify(recent)+'.\nӘңгімеден қысқа үзінді: '+JSON.stringify(history)+'.\nЖауап тілі: '+(LANG==='ru'?'орысша':'қазақша')+'.\nМұғалім сұрағы: '+question;
}


function renderChat(){const b=$('chatBody');if(!b)return;b.innerHTML=DB.chat.map(m=>`<div class="bubblemsg ${m.role==='user'?'me':'bot'}">${esc(m.text)}</div>`).join('')||'<div class="bubblemsg bot">Сәлеметсіз бе! Мен UstazERA мұғалім көмекшісімін. Сабақ, тапсырма, бағалау немесе студент нәтижесі бойынша сұраңыз.</div>';b.scrollTop=b.scrollHeight}
