function closeChat(){const p=$('chatPanel'),f=$('chatFab');if(p)p.classList.add('hidden');if(f)f.classList.remove('hidden')}
function initChat(){if(window._chatInit)return;window._chatInit=true;$('chatFab').onclick=openChat;$('chatClose').onclick=closeChat;$('chatSend').onclick=()=>botSend();$('chatInput').addEventListener('keydown',e=>{if(e.key==='Enter')botSend()});$('chatClear').onclick=()=>{DB.chat=[];persist();renderChat()};document.querySelectorAll('[data-chip]').forEach(b=>b.onclick=()=>botSend(b.dataset.chip))}
function copyText(t){try{if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(()=>toast('Көшірілді.'),()=>fallbackCopy(t));return}}catch(e){}fallbackCopy(t)}
function fallbackCopy(t){const a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();try{document.execCommand('copy');toast('Көшірілді.')}catch(e){toast('Көшіру мүмкін болмады: мәтінді өзіңіз белгілеңіз.')}a.remove()}
let currentTasks=null;
let taskMode='practice';
function tasksHistory(){const list=(DB.tasks=DB.tasks||[]);return list.length?list.map((t,i)=>`<div class="studentrow"><div><b>${esc(t.topic)} — ${t.type==='test'?'Тест':'Практикалық тапсырма'}</b><div class="muted small">${esc(t.subject)} · ${esc(t.group||'')} · ${new Date(t.created).toLocaleDateString()}</div></div><div class="actions" style="margin:0"><button class="btn soft" data-open-task="${i}">Ашу</button><button class="btn danger" data-del-task="${i}">Өшіру</button></div></div>`).join(''):'<div class="empty">Әзірге сақталған материал жоқ.</div>'}
function tasksPage(){return `${pageHead(tr('tasks'),'Бір бетте орналасқан екі тәуелсіз құрал: практикалық тапсырма құрастыру және тест дайындау.')} 
<div class="card"><div class="actions" style="margin:0 0 18px;gap:10px;flex-wrap:wrap"><button id="showPractice" class="btn primary">✦ Практикалық тапсырма</button><button id="showTest" class="btn soft">☷ Тест құрастыру</button></div>
<section id="practicePanel"><h2>Практикалық тапсырма жүйесі</h2><p class="muted small">Тек практикалық жұмыстар жасалады. Тест сұрақтары бұл бөлімге қосылмайды.</p><div class="formgrid">
<div class="field"><label>${tr('subject')} *</label><input id="prSubject" placeholder="Front-end web-ресурстарын әзірлеу"></div><div class="field"><label>${tr('topic')} *</label><input id="prTopic" placeholder="CSS Grid технологиясы"></div><div class="field"><label>${tr('group')}</label><input id="prGroup" placeholder="ПО-23-25"></div>
<div class="field"><label>Студент деңгейіне бейімдеу</label><select id="prStudent"><option value="">Барлық топқа / жалпы нұсқа</option>${DB.students.map(x=>`<option value="${esc(x.code)}">${esc(x.code)} · ${esc(x.group||'')}</option>`).join('')}</select></div>
<div class="field"><label>Қиындық деңгейі</label><select id="prLevel"><option>Аралас (A/B/C)</option><option>Жеңіл</option><option>Орташа</option><option>Күрделі</option></select></div><div class="field"><label>Практикалық тапсырма саны</label><select id="prCount"><option>3</option><option selected>5</option><option>8</option><option>10</option></select></div><div class="field"><label>Қосымша талаптар</label><textarea id="prExtra" placeholder="Мысалы: нақты өмірлік жағдай, код жазу, бағалау критерийлері"></textarea></div></div>
<div class="notice">Жеке студент таңдалса, оның деңгейі мен бұрынғы бағалау нәтижелері ескеріледі.</div><button id="makePractice" class="btn primary">✦ Практикалық тапсырмаларды жасау</button><div id="practiceResult" class="hidden" style="margin-top:18px"><div class="sectiontitle"><h3>Дайын практикалық тапсырмалар</h3><div class="actions" style="margin:0"><button id="copyPractice" class="btn soft">Көшіру</button><button id="savePractice" class="btn">Сақтау</button></div></div><textarea id="practiceOutput" rows="18"></textarea></div></section>
<section id="testPanel" class="hidden"><h2>Тест құрастыру жүйесі</h2><p class="muted small">Тек тест сұрақтары мен мұғалімге арналған жауап кілті жасалады. Практикалық тапсырмалар бөлек сақталады.</p><div class="formgrid">
<div class="field"><label>${tr('subject')} *</label><input id="tsSubject" placeholder="Front-end web-ресурстарын әзірлеу"></div><div class="field"><label>${tr('topic')} *</label><input id="tsTopic" placeholder="CSS Grid технологиясы"></div><div class="field"><label>${tr('group')}</label><input id="tsGroup" placeholder="ПО-23-25"></div>
<div class="field"><label>Тест деңгейі</label><select id="tsLevel"><option>Аралас (A/B/C)</option><option>Жеңіл</option><option>Орташа</option><option>Күрделі</option></select></div><div class="field"><label>Сұрақ саны</label><select id="tsCount"><option>5</option><option selected>10</option><option>15</option><option>20</option><option>25</option></select></div><div class="field"><label>Жауап нұсқалары</label><select id="tsOptions"><option value="4">4 нұсқа (A, B, C, D)</option><option value="3">3 нұсқа (A, B, C)</option></select></div><div class="field"><label>Қосымша талаптар</label><textarea id="tsExtra" placeholder="Мысалы: ситуациялық сұрақтар, код үзінділері, Блум таксономиясы"></textarea></div></div>
<div class="notice">Әр сұрақта бір ғана дұрыс жауап болады. Жауап кілті студентке көрсетілмейтін бөлек бөлімде беріледі.</div><button id="makeTest" class="btn primary">✦ Тест сұрақтарын жасау</button><div id="testResult" class="hidden" style="margin-top:18px"><div class="sectiontitle"><h3>Дайын тест</h3><div class="actions" style="margin:0"><button id="copyTest" class="btn soft">Көшіру</button><button id="saveTest" class="btn">Сақтау</button></div></div><textarea id="testOutput" rows="18"></textarea></div></section></div>
<div class="card" style="margin-top:16px"><h2>Сақталған материалдар</h2><div id="tasksHistory">${tasksHistory()}</div></div>`}
function setTaskMode(mode){taskMode=mode;$('practicePanel').classList.toggle('hidden',mode!=='practice');$('testPanel').classList.toggle('hidden',mode!=='test');$('showPractice').className='btn '+(mode==='practice'?'primary':'soft');$('showTest').className='btn '+(mode==='test'?'primary':'soft')}
function openTask(i){const t=DB.tasks[i];if(!t)return;setTaskMode(t.type==='test'?'test':'practice');if(t.type==='test'){$('tsSubject').value=t.subject||'';$('tsTopic').value=t.topic||'';$('tsGroup').value=t.group||'';$('testOutput').value=t.content||'';$('testResult').classList.remove('hidden')}else{$('prSubject').value=t.subject||'';$('prTopic').value=t.topic||'';$('prGroup').value=t.group||'';$('prStudent').value=t.studentCode||'';$('practiceOutput').value=t.content||'';$('practiceResult').classList.remove('hidden')}}
async function generatePractice(){const subject=$('prSubject').value.trim(),topic=$('prTopic').value.trim();if(!subject||!topic)return toast('Пән мен тақырыпты толтырыңыз.');const level=$('prLevel').value,n=$('prCount').value,group=$('prGroup').value.trim(),extra=$('prExtra').value.trim(),studentCode=$('prStudent').value,student=studentCode?DB.students.find(x=>x.code===studentCode):null,history=studentCode?DB.grades.filter(g=>g.code===studentCode).map(g=>({topic:g.topic,score:g.score,note:g.note,practice:g.practice})) :[];const b=$('makePractice');b.disabled=true;b.textContent='AI тапсырмаларды дайындап жатыр…';try{const prompt=`Колледжге арналған дәл ${n} практикалық тапсырма құрастыр. Пән: ${subject}. Тақырып: ${topic}. Топ: ${group||'көрсетілмеген'}. Деңгей: ${level}. Қосымша талап: ${extra||'жоқ'}. Тіл: ${LANG==='kk'?'қазақша':'орысша'}. ${student?`Студент коды: ${student.code}; деңгейі: ${student.level}; ескертпе: ${student.notes||'жоқ'}; алдыңғы бағалары: ${JSON.stringify(history)}. Осы деректерге сүйеніп жеке бейімде.`:'Жалпы топқа арнап дайында.'} Әр тапсырмада атауы, оқу мақсаты, нақты нұсқаулық, орындалу қадамдары, тапсыратын нәтиже және 100 балдық бағалау критерийлері болсын. Деңгей аралас болса A базалық, B қолдану, C күрделі болсын. Тест сұрақтарын қоспа. Артық кіріспесіз дайын тапсырмаларды нөмірлеп бер.`;const content=await askAI(prompt,{maxTokens:Math.min(6144,Math.max(2048,512+Number(n)*450))});$('practiceOutput').value=content;$('practiceResult').classList.remove('hidden');$('practiceResult').scrollIntoView({behavior:'smooth',block:'start'});currentTasks={type:'practice',subject,topic,group,studentCode,content,created:Date.now()}}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='✦ Практикалық тапсырмаларды жасау'}}
async function generateTest(){const subject=$('tsSubject').value.trim(),topic=$('tsTopic').value.trim();if(!subject||!topic)return toast('Пән мен тақырыпты толтырыңыз.');const level=$('tsLevel').value,n=$('tsCount').value,opts=$('tsOptions').value,group=$('tsGroup').value.trim(),extra=$('tsExtra').value.trim(),b=$('makeTest');b.disabled=true;b.textContent='AI тестті дайындап жатыр…';try{const prompt=`Колледжге арналған дәл ${n} тест сұрағын құрастыр. Пән: ${subject}. Тақырып: ${topic}. Топ: ${group||'көрсетілмеген'}. Деңгей: ${level}. Әр сұрақта дәл ${opts} жауап нұсқасы болсын (${opts==='4'?'A, B, C, D':'A, B, C'}). Қосымша талап: ${extra||'жоқ'}. Тіл: ${LANG==='kk'?'қазақша':'орысша'}. Сұрақтар мазмұнды, қайталанбайтын, оқу мақсатына сай болсын; әрқайсысында бір ғана даусыз дұрыс жауап болсын. Жауапты екі айқын бөлікке бөл: 1) СТУДЕНТКЕ АРНАЛҒАН ТЕСТ — дұрыс жауаптарды белгілеме; 2) МҰҒАЛІМГЕ АРНАЛҒАН ЖАУАП КІЛТІ — әр сұрақтың дұрыс әрпін және қысқа түсіндірмесін бер. Практикалық тапсырма қоспа.`;const content=await askAI(prompt,{maxTokens:Math.min(4608,Math.max(1536,512+Number(n)*160))});$('testOutput').value=content;$('testResult').classList.remove('hidden');$('testResult').scrollIntoView({behavior:'smooth',block:'start'});currentTasks={type:'test',subject,topic,group,content,created:Date.now()}}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='✦ Тест сұрақтарын жасау'}}
function saveTask(type){const content=$(type==='test'?'testOutput':'practiceOutput').value;if(!content.trim())return toast('Алдымен материалды жасаңыз.');const prefix=type==='test'?'ts':'pr';const item={...(currentTasks&&currentTasks.type===type?currentTasks:{}),type,subject:$(prefix+'Subject').value.trim(),topic:$(prefix+'Topic').value.trim(),group:$(prefix+'Group').value.trim(),content,created:Date.now()};if(type==='practice')item.studentCode=$('prStudent').value;DB.tasks=DB.tasks||[];DB.tasks.unshift(item);persist();$('tasksHistory').innerHTML=tasksHistory();wireTaskHistory();toast('Материал сақталды.')}
function wireTasks(){$('showPractice').onclick=()=>setTaskMode('practice');$('showTest').onclick=()=>setTaskMode('test');$('makePractice').onclick=generatePractice;$('makeTest').onclick=generateTest;$('copyPractice').onclick=()=>copyText($('practiceOutput').value);$('copyTest').onclick=()=>copyText($('testOutput').value);$('savePractice').onclick=()=>saveTask('practice');$('saveTest').onclick=()=>saveTask('test');wireTaskHistory()}
function wireTaskHistory(){document.querySelectorAll('[data-open-task]').forEach(b=>b.onclick=()=>openTask(+b.dataset.openTask));document.querySelectorAll('[data-del-task]').forEach(b=>b.onclick=()=>{if(!confirm('Осы материалды өшіресіз бе?'))return;DB.tasks.splice(+b.dataset.delTask,1);persist();$('tasksHistory').innerHTML=tasksHistory();wireTaskHistory()})}

function setPage(p){page=p;render();document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('crumb').textContent=tr(p)}
function pageHead(title,sub,action=''){return `<div class="pagehead"><div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function stat(icon,label,value){return `<div class="card stat"><div class="bubble">${icon}</div><div><small>${label}</small><b>${value}</b></div></div>`}
function recentRows(){return DB.grades.slice().sort((a,b)=>b.date-a.date).slice(0,6).map(g=>`<tr><td><b>${esc(g.code)}</b></td><td>${esc(g.topic)}</td><td><span class="score">${g.score}%</span></td><td><span class="pill ${g.score>=75?'good':g.score>=50?'warn':'warn'}">${g.score>=75?'Жақсы':g.score>=50?'Орташа':'Қолдау қажет'}</span></td></tr>`).join('')}
function home(){const avg=DB.grades.length?Math.round(DB.grades.reduce((s,g)=>s+g.score,0)/DB.grades.length):0;return `${pageHead(tr('welcome')+', '+esc(USER)+'!',tr('subtitle'))}<div class="grid stats">${stat('♙',tr('studentCount'),DB.students.length)}${stat('✓',tr('gradeCount'),DB.grades.length)}${stat('◉',tr('average'),avg+'%')}${stat('▤',tr('packages'),DB.packages.length)}</div><div class="grid cols"><div class="card"><h2>${tr('quick')}</h2><div class="grid three"><button class="btn soft" data-go="package">✦ ${tr('create')}</button><button class="btn soft" data-go="students">＋ ${tr('addStudent')}</button><button class="btn soft" data-go="bot">◉ ${tr('openBot')}</button></div><div style="height:22px"></div><h2>${tr('recent')}</h2><div class="tablewrap"><table><thead><tr><th>Код</th><th>Тақырып</th><th>Нәтиже</th><th>Деңгей</th></tr></thead><tbody>${recentRows()||`<tr><td colspan="4" class="empty">${tr('noData')}</td></tr>`}</tbody></table></div></div><div class="card"><h2>UstazERA мүмкіндіктері</h2><div class="recommend"><b>1. Сабақ пакеті</b><div class="muted small">Бір тақырыптан 8 оқу материалын дайындау</div></div><div class="recommend"><b>2. Бағалау және аналитика</b><div class="muted small">Студенттердің нәтижесін салыстыру және оқу қиындығын табу</div></div><div class="recommend"><b>3. Мұғалімге арналған бот</b><div class="muted small">Сабақ, тапсырма, бағалау және жеке жұмыс бойынша кеңес</div></div><div class="notice warn small">AI ұсынған баға мен педагогикалық шешімді мұғалім тексеріп, өзі бекітеді. Студенттің аты-жөнін емес, кодын қолданыңыз.</div></div></div>`}
function packagePage(){return `${pageHead('Бір сабақ — толық оқу пакеті','Бір рет мәлімет енгізіңіз. AI сабақ жоспарын, презентацияны, тапсырмаларды және бағалау материалдарын бірізді дайындайды.')}<div class="card"><div class="formgrid"><div class="field"><label>${tr('subject')} *</label><input id="pSubject" placeholder="Front-end web-ресурстарын әзірлеу"></div><div class="field"><label>${tr('group')}</label><input id="pGroup" placeholder="ПО-23-25"></div><div class="field"><label>${tr('topic')} *</label><input id="pTopic" placeholder="CSS Grid технологиясы"></div><div class="field"><label>${tr('duration')}</label><select id="pDuration"><option>90 минут</option><option>80 минут</option><option>45 минут</option></select></div><div class="field"><label>${tr('goal')}</label><textarea id="pGoal" placeholder="Студент CSS Grid көмегімен торлы макет құрастырады"></textarea></div><div class="field"><label>Қосымша талаптар / Дополнительные требования</label><textarea id="pExtra" placeholder="Тіл, деңгей, құралдар, бағалау шарттары"></textarea></div></div><div class="notice">AI төмендегі 8 бөлімді бір оқу мақсатына сәйкестендіріп дайындайды. Дайын материалды мұғалім өңдеп, тексергеннен кейін қолданады.</div><button id="makePackage" class="btn primary">✦ ${tr('generate')} — 8 бөлім</button></div><div id="packageResult" class="card hidden" style="margin-top:16px"><div class="sectiontitle"><h2>Дайын оқу пакеті</h2><button id="savePackage" class="btn">▣ Сақтау</button></div><div id="packageItems" class="grid packagegrid"></div></div><div id="packageHistory" style="margin-top:16px">${packageHistory()}</div>`}
function packageHistory(){return `<div class="card"><h2>Сақталған оқу пакеттері</h2>${DB.packages.length?DB.packages.map((p,i)=>`<div class="studentrow"><div><b>${esc(p.topic)}</b><div class="muted small">${esc(p.subject)} · ${esc(p.group||'')}</div></div><button class="btn" data-open-package="${i}">Ашу</button></div>`).join(''):'<div class="empty">Әзірге сақталған пакет жоқ.</div>'}</div>`}
let currentPackage=null;
const packageNames=['Сабақ жоспары','Презентация құрылымы','Деңгейлік практикалық тапсырмалар','Тест сұрақтары','Бағалау рубрикасы','Анимация сценарийі','Рефлексия','Үй тапсырмасы'];
function renderPackageResult(data){currentPackage=data;$('packageResult').classList.remove('hidden');$('packageItems').innerHTML=packageNames.map((n,i)=>`<div class="packageitem"><h3>${i+1}. ${n}</h3><textarea data-pkg="${i}">${esc(data.sections[i]||'')}</textarea></div>`).join('');$('packageResult').scrollIntoView({behavior:'smooth',block:'start'})}
async function makePackage(){
 const subject=$('pSubject').value.trim(),topic=$('pTopic').value.trim();
 if(!subject||!topic)return toast('Пән мен тақырыпты толтырыңыз.');
 const b=$('makePackage');b.disabled=true;b.textContent='AI дайындап жатыр…';
 try{
  const prompt=`Колледж оқытушысына біртұтас оқу пакетін дайында. Пән: ${subject}. Топ: ${$('pGroup').value}. Тақырып: ${topic}. Ұзақтығы: ${$('pDuration').value}. Оқу мақсаты: ${$('pGoal').value||'тақырыпқа сай нақты оқу мақсатын құрастыр'}. Қосымша талап: ${$('pExtra').value}. Тіл: ${LANG==='kk'?'қазақша':'орысша'}. Бір оқу мақсаты мен терминология барлық бөлімде бірізді болсын. Нақты емес стандарт/дерек ойдан шығарма. Әр бөлімді дәл мына белгілермен баста: [1] САБАҚ ЖОСПАРЫ (кезеңдер, минут, оқытушы/студент әрекеті, бағалау); [2] ПРЕЗЕНТАЦИЯ (6-8 слайд атауы және негізгі мазмұны); [3] ДЕҢГЕЙЛІК ТАПСЫРМАЛАР (A/B/C үш деңгей, нұсқаулық және күтілетін нәтиже); [4] ТЕСТ (5 сұрақ, 4 нұсқа және дұрыс жауап кілті мұғалімге); [5] БАҒАЛАУ РУБРИКАСЫ (критерийлер және жалпы 100 балл); [6] АНИМАЦИЯ СЦЕНАРИЙІ (4-6 көрініс, визуал және диктор мәтіні); [7] РЕФЛЕКСИЯ (3 сұрақ/әдіс); [8] ҮЙ ТАПСЫРМАСЫ (міндетті және шығармашылық деңгей).`;
  const answer=await askAI(prompt,{maxTokens:AI_TOKEN_LIMITS.package});const sections=answer.split(/(?=\[(?:[1-8])\]\s*)/).filter(Boolean);const mapped=Array(8).fill('');sections.slice(0,8).forEach((x,i)=>mapped[i]=x.trim());if(!mapped.some(Boolean))mapped[0]=answer;
  currentPackage={subject,group:$('pGroup').value,topic,sections:mapped,created:Date.now()};renderPackageResult(currentPackage);
 }catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='✦ AI арқылы жасау — 8 бөлім'}
}
